    <table style="width:100%">
      <tr>
        <td width="48%" style="padding-right:4%">
          <div class="section">
            <p class="section-title">Detalles de Llegada</p>
            <p><span class="label">Origen:</span><br/><span class="value">${res.origin}</span></p>
            <p><span class="label">Fecha:</span><br/><span class="value">${res.dateArrival}</span></p>
            <p><span class="label">Vuelo/Aerolínea:</span><br/><span class="value">${res.flightNoArrival} / ${res.airlineArrival}</span></p>
            <p><span class="label">Hora Llegada:</span><br/><span class="value">${res.arrivalTime}</span></p>
          </div>
        </td>
        <td width="48%">
          <div class="section">
