                        <div className="absolute z-[100] left-0 right-0 mt-3 bg-white border border-gray-100 rounded-3xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2">
                          {suggestions.map((s, i) => (
                            <button key={i} onClick={() => selectSuggestion(s)} className="w-full text-left p-4 hover:bg-blue-50 border-b border-gray-50 last:border-0 group transition-colors">
                              <p className="text-[11px] font-black text-slate-800 group-hover:text-blue-600 uppercase tracking-tight">{s.name}</p>
                              <p className="text-[9px] text-gray-400 font-bold uppercase mt-1">{s.address}</p>
                            </button>
                          ))}
                        </div>
                      )}
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                      <InputGroup label="Fecha" name="dateArrival" type="date" value={formData.dateArrival} onChange={handleInputChange} />
                      <InputGroup label="Hora" name="arrivalTime" type="time" value={formData.arrivalTime} onChange={handleInputChange} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <InputGroup label="Aerolínea" name="airlineArrival" value={formData.airlineArrival} onChange={handleInputChange} />
                      <InputGroup label="No. Vuelo" name="flightNoArrival" value={formData.flightNoArrival} onChange={handleInputChange} />
                    </div>
                  </div>

                  {/* Salida */}
                  <div className="space-y-6 bg-[#fdfaf8] p-8 rounded-[32px] border border-orange-50 shadow-sm">
                    <SectionTitle label="Servicio Salida" icon="fa-plane-departure" color="bg-orange-50 text-orange-600" />
                    <InputGroup label="Origen Pickup" name="originDeparture" value={formData.originDeparture} onChange={handleInputChange} placeholder="Ej: Lobby del Hotel" />
                    <div className="grid grid-cols-2 gap-4">
                      <InputGroup label="Fecha" name="dateDeparture" type="date" value={formData.dateDeparture} onChange={handleInputChange} />
                      <InputGroup label="Pick-up Hotel" name="departureTimeHotel" type="time" value={formData.departureTimeHotel} highlight />
                    </div>
                    <InputGroup label="Aerolínea / Terminal" name="airlineDeparture" value={formData.airlineDeparture} onChange={handleInputChange} placeholder="Destino Aeropuerto" />
                    <InputGroup label="Hora del Vuelo" name="departureTimeFlight" type="time" value={formData.departureTimeFlight} onChange={handleInputChange} />
                  </div>
                </div>

                <div className="mt-12 flex flex-col sm:flex-row gap-4 pt-8 border-t border-gray-50">
                  <button onClick={handleSave} className="flex-1 py-5 bg-[#0a305e] text-white rounded-[24px] font-black uppercase text-[11px] tracking-[0.2em] shadow-xl shadow-blue-100 hover:bg-slate-900 hover:scale-[1.01] active:scale-95 transition-all">
                    {editingId ? 'Actualizar Información' : 'Generar y Guardar Voucher'}
                  </button>
                  <button onClick={handleSyncToSheets} className="px-10 py-5 bg-[#34a853] text-white rounded-[24px] font-black uppercase text-[11px] tracking-[0.2em] shadow-xl shadow-green-100 hover:bg-green-600 hover:scale-[1.01] active:scale-95 transition-all flex items-center justify-center gap-3">
                    <i className="fas fa-table"></i> {syncing ? 'Sincronizando...' : 'Guardar en Sheets'}
                  </button>
                </div>
              </section>

              {currentVoucher && (
                <div className="animate-in fade-in slide-in-from-bottom-12 duration-700">
                  <div className="text-center mb-8">
                    <h3 className="text-3xl font-black text-slate-800 uppercase tracking-tighter">Vista Previa Profesional</h3>
                    <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-2">Documento listo para exportación</p>
                  </div>

                  <VoucherPreview reservation={currentVoucher} />

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mt-12 max-w-4xl mx-auto">
                    <button onClick={handleExportPDF} className="group bg-red-600 text-white p-6 rounded-[32px] font-black uppercase text-[10px] tracking-widest shadow-xl shadow-red-100 hover:bg-red-700 transition-all active:scale-95 flex flex-col items-center gap-2">
                      <i className="fas fa-file-pdf text-2xl group-hover:scale-110 transition-transform"></i>
                      Descargar PDF Profesional
                    </button>
                    <button onClick={() => downloadAsGoogleDoc(currentVoucher)} className="group bg-white border-2 border-blue-100 text-[#0a305e] p-6 rounded-[32px] font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-50 hover:bg-blue-50 transition-all active:scale-95 flex flex-col items-center gap-2">
                      <i className="fas fa-file-word text-2xl group-hover:scale-110 transition-transform"></i>
                      Guardar como Google Doc
                    </button>
                    <button onClick={() => window.print()} className="group bg-slate-900 text-white p-6 rounded-[32px] font-black uppercase text-[10px] tracking-widest shadow-xl shadow-slate-200 hover:bg-black transition-all active:scale-95 flex flex-col items-center gap-2">
                      <i className="fas fa-print text-2xl group-hover:scale-110 transition-transform"></i>
                      Imprimir Documento
                    </button>
                  </div>
                </div>
              )}
            </div>
          ) : (
            <div className="max-w-6xl mx-auto animate-in fade-in duration-500">
              <div className="bg-white rounded-[40px] shadow-2xl overflow-hidden border border-gray-100">
                <div className="p-10 border-b bg-slate-900 text-white flex flex-col md:flex-row justify-between items-center gap-6">
                  <div>
                    <h2 className="text-3xl font-black uppercase tracking-tighter">Historial de Reservaciones</h2>
                    <p className="text-xs font-bold uppercase text-slate-400 mt-2 tracking-widest">Gestionando {reservations.length} servicios registrados</p>
                  </div>
                  <button onClick={handleSyncToSheets} className="bg-green-500 hover:bg-green-600 px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-green-900/20 transition-all flex items-center gap-3">
                    <i className="fas fa-external-link-alt"></i> Subir a Google Drive
                  </button>
                </div>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-400 uppercase text-[9px] font-black tracking-widest border-b border-gray-100">
                      <tr>
                        <th className="px-10 py-6">ID Reserva</th>
                        <th className="px-10 py-6">Pasajero Principal</th>
                        <th className="px-10 py-6">Llegada</th>
                        <th className="px-10 py-6">Salida</th>
                        <th className="px-10 py-6 text-center">Acciones</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                      {reservations.length === 0 ? (
                        <tr>
                          <td colSpan={5} className="px-10 py-20 text-center">
                            <i className="fas fa-folder-open text-gray-200 text-5xl mb-4"></i>
                            <p className="text-gray-400 font-bold uppercase text-xs">No hay reservaciones guardadas</p>
                          </td>
                        </tr>
                      ) : (
                        reservations.map(res => (
                          <tr key={res.id} className="hover:bg-blue-50/40 transition-colors group">
                            <td className="px-10 py-6 font-mono font-bold text-blue-600 text-sm">{res.reservationNo}</td>
                            <td className="px-10 py-6 font-black text-slate-700 uppercase text-xs">{res.name}</td>
                            <td className="px-10 py-6 text-[10px] font-bold text-green-600 uppercase tracking-tighter">{res.dateArrival} <br/> <span className="text-slate-400">{res.arrivalTime}</span></td>
                            <td className="px-10 py-6 text-[10px] font-bold text-orange-600 uppercase tracking-tighter">{res.dateDeparture} <br/> <span className="text-slate-400">{res.departureTimeHotel}</span></td>
                            <td className="px-10 py-6 text-center">
                              <div className="flex justify-center gap-2">
                                <button onClick={() => { setCurrentVoucher(res); setActiveTab('create'); }} className="w-10 h-10 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-600 hover:text-white transition-all"><i className="fas fa-eye"></i></button>
                                <button onClick={() => handleEdit(res)} className="w-10 h-10 bg-orange-50 text-orange-500 rounded-xl hover:bg-orange-500 hover:text-white transition-all"><i className="fas fa-edit"></i></button>
                              </div>
                            </td>
                          </tr>
                        ))
                      )}
                    </tbody>
                  </table>
                </div>
                <div className="p-10 bg-slate-50 border-t border-gray-100 flex justify-center">
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Quick Travel Cancun Management System • Beta v3.1</p>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Control Panel (WhatsApp) Desktop */}
      <aside className="hidden xl:flex w-80 flex-col gap-8 p-10 bg-white border-l border-slate-100 shadow-2xl relative z-[100]">
        <div className="space-y-2">
          <h3 className="text-xs font-black uppercase text-slate-400 tracking-[0.2em] flex items-center gap-2">
            <i className="fab fa-whatsapp text-green-500"></i> Comunicar Voucher
          </h3>
          <p className="text-[10px] text-gray-400 font-bold leading-relaxed">Envíe los detalles a través de canales directos de WhatsApp.</p>
        </div>

        <div className="space-y-8 mt-4">
          <WhatsAppBtn icon="fa-taxi" color="bg-[#25D366]" label="Al Chofer" onClick={() => triggerWhatsAppModal('driver')} />
          <WhatsAppBtn icon="fa-user-tie" color="bg-[#0a305e]" label="Al Agente Staff" onClick={() => triggerWhatsAppModal('staff')} />
          <WhatsAppBtn icon="fa-headset" color="bg-[#f05a28]" label="Al Cliente" onClick={() => triggerWhatsAppModal('customer')} />
        </div>

        <div className="mt-auto bg-slate-50 p-6 rounded-3xl border border-slate-100">
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-3">Sincronización Drive</p>
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-green-500 shadow-sm border border-slate-100">
              <i className="fas fa-cloud-upload-alt"></i>
            </div>
            <div>
              <p className="text-[10px] font-black text-slate-800 uppercase leading-none">{SHEET_NAME}</p>
              <p className="text-[8px] text-slate-400 font-bold mt-1 uppercase">{COMPANY_EMAIL}</p>
            </div>
          </div>
        </div>
      </aside>

      {/* Mobile WhatsApp Floating Actions */}
      <div className="xl:hidden fixed bottom-10 right-10 flex flex-col gap-4 z-[150]">
        <button onClick={() => triggerWhatsAppModal('customer')} className="w-16 h-16 bg-[#f05a28] text-white rounded-[24px] shadow-2xl flex items-center justify-center text-xl hover:scale-110 active:scale-90 transition-all"><i className="fas fa-headset"></i></button>
        <button onClick={() => triggerWhatsAppModal('staff')} className="w-16 h-16 bg-[#0a305e] text-white rounded-[24px] shadow-2xl flex items-center justify-center text-xl hover:scale-110 active:scale-90 transition-all"><i className="fas fa-user-tie"></i></button>
        <button onClick={() => triggerWhatsAppModal('driver')} className="w-16 h-16 bg-[#25D366] text-white rounded-[24px] shadow-2xl flex items-center justify-center text-xl hover:scale-110 active:scale-90 transition-all"><i className="fas fa-taxi"></i></button>
      </div>
    </div>
  );
};

const SectionTitle: React.FC<{ label: string; icon: string; color: string }> = ({ label, icon, color }) => (
  <div className="flex items-center gap-3 mb-6">
    <div className={`w-10 h-10 ${color} rounded-xl flex items-center justify-center shadow-sm`}>
      <i className={`fas ${icon}`}></i>
    </div>
    <h3 className="text-xs font-black text-slate-800 uppercase tracking-widest">{label}</h3>
  </div>
);

const InputGroup: React.FC<{ label: string; name: string; type?: string; value: string; onChange?: any; placeholder?: string; highlight?: boolean }> = ({ label, name, type = 'text', value, onChange, placeholder, highlight = false }) => (
  <div className="flex flex-col group">
    <label className="text-[10px] uppercase font-black text-gray-400 mb-2 tracking-widest pl-1 group-focus-within:text-blue-500 transition-colors">{label}</label>
    <input 
      type={type} 
      name={name} 
      value={value} 
      onChange={onChange} 
      placeholder={placeholder} 
      className={`border-2 border-gray-100 rounded-2xl px-5 py-4 text-sm font-bold text-slate-800 bg-white focus:border-blue-500 focus:ring-4 focus:ring-blue-50 outline-none transition-all shadow-sm ${highlight ? 'text-orange-600 border-orange-50' : ''}`} 
    />
  </div>
);

const WhatsAppBtn: React.FC<{ icon: string; color: string; label: string; onClick: () => void }> = ({ icon, color, label, onClick }) => (
  <button onClick={onClick} className="flex flex-col items-center group w-full">
    <div className={`w-full h-20 ${color} text-white rounded-[32px] flex flex-col items-center justify-center shadow-xl shadow-slate-200 transform group-hover:scale-105 group-hover:-translate-y-1 group-active:scale-95 transition-all duration-300 relative overflow-hidden`}>
      <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
      <i className={`fas ${icon} text-2xl mb-1`}></i>
      <span className="text-[9px] font-black uppercase tracking-tighter opacity-80">{label}</span>
    </div>
  </button>
);

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Reservation } from './types';
import { CONTACTS, COMPANY_EMAIL, SHEET_NAME, COLORS } from './constants';
import { getWhatsAppLink, generateWhatsAppMessage, downloadAsGoogleDoc, downloadAsPDF } from './utils';
import VoucherPreview from './components/VoucherPreview';
import { GoogleGenAI } from "@google/genai";

const GOOGLE_SHEET_URL = "https://docs.google.com/spreadsheets/d/1mKo7CYV3Wf1LmuuslP0DmV9UTUFvGvE1JKFQihqFLvE/edit?usp=drivesdk";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'history'>('create');
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [currentVoucher, setCurrentVoucher] = useState<Reservation | null>(null);
  const [syncing, setSyncing] = useState(false);
  const [isExportingPDF, setIsExportingPDF] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Estados para búsqueda de Hoteles
  const [suggestions, setSuggestions] = useState<{name: string, address: string}[]>([]);
  const [isSearchingHotels, setIsSearchingHotels] = useState(false);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const searchTimeout = useRef<any>(null);

  // Estado para el modal de WhatsApp
  const [showWSModal, setShowWSModal] = useState<{
    show: boolean;
    type: 'driver' | 'staff' | 'customer' | null;
    number: string;
    label: string;
  }>({ show: false, type: null, number: '', label: '' });

  const generateNewId = () => {
    const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    let randomPart = '';
    for (let i = 0; i < 6; i++) {
      randomPart += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return `QTC${randomPart}`;
  };

  const initialFormState: Omit<Reservation, 'id' | 'createdAt'> = {
    reservationNo: '',
    name: '',
    origin: 'Aeropuerto Cancún (T2/T3/T4)',
    destination: '',
    dateArrival: new Date().toISOString().split('T')[0],
    dateDeparture: new Date().toISOString().split('T')[0],
    arrivalTime: '',
    flightNoArrival: '',
    airlineArrival: '',
    airlineDeparture: '',
    originDeparture: '',
    departureTimeHotel: '',
    departureTimeFlight: '',
    peopleCount: 1,
    balanceMxn: 0,
    balanceUsd: 0,
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    const saved = localStorage.getItem('qt_reservations');
    if (saved) {
      const parsed = JSON.parse(saved);
      setReservations(parsed);
      if (!editingId && formData.reservationNo === '') {
        setFormData(prev => ({ ...prev, reservationNo: generateNewId() }));
      }
    } else {
      if (!editingId && formData.reservationNo === '') {
        setFormData(prev => ({ ...prev, reservationNo: generateNewId() }));
      }
    }
  }, [editingId, formData.reservationNo]);

  const searchHotels = async (query: string) => {
    if (query.length < 3) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }

    setIsSearchingHotels(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Lista 5 hoteles o lugares populares en Cancún que coincidan con "${query}". Devuelve solo nombres de hoteles y direcciones en formato JSON: [{"name": "...", "address": "..."}]`,
        config: {
          responseMimeType: "application/json"
        },
      });

      const text = response.text || "[]";
      const newSuggestions = JSON.parse(text);

      setSuggestions(newSuggestions);
      setShowSuggestions(newSuggestions.length > 0);
    } catch (error) {
      console.error("Error searching hotels:", error);
    } finally {
      setIsSearchingHotels(false);
    }
  };

  const handleDestinationChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    setFormData(prev => ({ ...prev, destination: val }));

    if (searchTimeout.current) clearTimeout(searchTimeout.current);
    searchTimeout.current = setTimeout(() => {
      searchHotels(val);
    }, 600);
  };

  const selectSuggestion = (s: {name: string, address: string}) => {
    setFormData(prev => ({ ...prev, destination: `${s.name}, ${s.address}` }));
    setShowSuggestions(false);
    setSuggestions([]);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ 
      ...prev, 
      [name]: (name === 'peopleCount' || name === 'balanceMxn' || name === 'balanceUsd') 
        ? parseFloat(value) || 0 
        : value 
    }));
  };

  const showUIMessage = (msg: string) => {
    setSuccessMessage(msg);
    setTimeout(() => setSuccessMessage(null), 5000);
  };

  const handleSave = () => {
    if (!formData.name || !formData.destination) {
      alert('Por favor, complete al menos el nombre del cliente y el hotel de destino.');
      return;
    }

    setIsSaving(true);
    let updated: Reservation[];
    let savedRes: Reservation;

    if (editingId) {
      updated = reservations.map(res => {
        if (res.id === editingId) {
          savedRes = { ...formData, id: editingId, createdAt: res.createdAt } as Reservation;
          return savedRes;
        }
        return res;
      });
      showUIMessage(`✅ Reserva ${formData.reservationNo} actualizada con éxito.`);
    } else {
      const newRes: Reservation = {
        ...formData,
        id: Date.now().toString(),
        createdAt: new Date().toISOString(),
      } as Reservation;
      savedRes = newRes;
      updated = [newRes, ...reservations];
      showUIMessage(`✅ Reserva ${newRes.reservationNo} guardada localmente.`);
    }

    setReservations(updated);
    localStorage.setItem('qt_reservations', JSON.stringify(updated));
    setCurrentVoucher(savedRes!);

    setTimeout(() => {
      setIsSaving(false);
      setEditingId(null);
      setFormData({
        ...initialFormState,
        reservationNo: generateNewId()
      });
    }, 600);
  };

  // Fixed missing handleEdit function
  const handleEdit = (res: Reservation) => {
    setEditingId(res.id);
    const { id, createdAt, ...dataToEdit } = res;
    setFormData(dataToEdit);
    setActiveTab('create');
    setCurrentVoucher(null);
  };

  const handleSyncToSheets = async () => {
    setSyncing(true);
    // Simulación de carga en Drive
    console.log(`Subiendo archivo '${SHEET_NAME}' a Google Drive de ${COMPANY_EMAIL}`);
    setTimeout(() => {
      setSyncing(false);
      window.open(GOOGLE_SHEET_URL, '_blank');
      showUIMessage(`📊 Datos sincronizados en Google Drive (${COMPANY_EMAIL}) bajo el nombre "${SHEET_NAME}".`);
    }, 1500);
  };

  const handleExportPDF = async () => {
    if (!currentVoucher) return;
    setIsExportingPDF(true);
    await downloadAsPDF('voucher-to-print', `Voucher_${currentVoucher.reservationNo}.pdf`);
    setIsExportingPDF(false);
    showUIMessage(`📄 PDF profesional generado en una sola hoja.`);
  };

  const triggerWhatsAppModal = (type: 'driver' | 'staff' | 'customer') => {
    const voucher = currentVoucher || formData;
    if (!voucher.name || !voucher.reservationNo) {
      alert('Primero complete o guarde la información de la reservación');
      return;
    }

    let defaultNum = '';
    let label = '';
    if (type === 'driver') { defaultNum = CONTACTS.DRIVER.number; label = 'Chofer'; }
    if (type === 'staff') { defaultNum = CONTACTS.STAFF.number; label = 'Agente Staff'; }
    if (type === 'customer') { defaultNum = CONTACTS.CUSTOMER.number; label = 'Cliente'; }

    setShowWSModal({ show: true, type, number: defaultNum, label });
  };

  const confirmAndSendWhatsApp = () => {
    const voucher = currentVoucher || formData;
    const message = generateWhatsAppMessage(voucher as Reservation);
    window.open(getWhatsAppLink(showWSModal.number, message), '_blank');
    setShowWSModal(prev => ({ ...prev, show: false }));
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col xl:flex-row font-sans text-slate-800 selection:bg-blue-100">
      {/* WhatsApp Modal */}
      {showWSModal.show && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center bg-slate-900/40 backdrop-blur-md p-4 animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-sm rounded-[40px] shadow-2xl overflow-hidden animate-in zoom-in duration-200">
            <div className="bg-[#0a305e] p-8 text-white text-center">
              <div className="w-16 h-16 bg-white/10 rounded-full flex items-center justify-center mx-auto mb-4">
                <i className="fab fa-whatsapp text-4xl text-green-400"></i>
              </div>
              <h3 className="text-2xl font-black uppercase tracking-tighter">Enviar a {showWSModal.label}</h3>
              <p className="text-[11px] opacity-60 uppercase font-bold tracking-widest mt-1">Confirmar envío de Voucher</p>
            </div>
            <div className="p-8 space-y-6">
              <InputGroup label="Número de WhatsApp" name="wsNum" value={showWSModal.number} onChange={(e: any) => setShowWSModal(p => ({...p, number: e.target.value}))} />
              <div className="flex gap-4">
                <button onClick={() => setShowWSModal(p => ({...p, show: false}))} className="flex-1 py-4 bg-gray-100 text-gray-500 rounded-2xl font-black uppercase text-[10px] tracking-widest hover:bg-gray-200 transition-colors">Cancelar</button>
                <button onClick={confirmAndSendWhatsApp} className="flex-2 py-4 bg-[#25D366] text-white rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-lg shadow-green-200 hover:bg-green-600 transition-all active:scale-95">Abrir WhatsApp</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Notificaciones */}
      {successMessage && (
        <div className="fixed top-8 left-1/2 -translate-x-1/2 z-[300] w-full max-w-md px-6 animate-in slide-in-from-top-4 duration-300">
          <div className="bg-slate-900 text-white px-8 py-5 rounded-3xl shadow-2xl flex items-center justify-between border border-white/10">
            <div className="flex items-center gap-4">
              <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse"></div>
              <span className="font-bold text-xs uppercase tracking-tight">{successMessage}</span>
            </div>
            <button onClick={() => setSuccessMessage(null)} className="opacity-40 hover:opacity-100"><i className="fas fa-times"></i></button>
          </div>
        </div>
      )}

