            </div>
          </div>

          <nav className="flex bg-gray-100 p-1.5 rounded-2xl">
            <button onClick={() => setActiveTab('create')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'create' ? 'bg-white text-[#0a305e] shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>Nuevo Voucher</button>
            <button onClick={() => setActiveTab('history')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'bg-white text-[#0a305e] shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}>Reservaciones</button>
