                    <span className="font-mono text-lg font-black text-blue-600">{formData.reservationNo}</span>
                  </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                  {/* General */}
                  <div className="space-y-6">
