                    <InputGroup label="Nombre Pasajero" name="departureName" value={formData.departureName} onChange={handleInputChange} placeholder="Nombre en salida" />
                    <InputGroup label="Origen Pickup" name="originDeparture" value={formData.originDeparture} onChange={handleInputChange} placeholder="Ej: Lobby" />
                    <InputGroup label="Destino de Salida" name="departureDestination" value={formData.departureDestination} onChange={handleInputChange} placeholder="Destino..." />
                    <div className="grid grid-cols-2 gap-4">
                      <InputGroup label="Pax Salida" name="peopleCountDeparture" type="number" value={formData.peopleCountDeparture.toString()} onChange={handleInputChange} />
                      <InputGroup label="Pick-up Hotel" name="departureTimeHotel" type="time" value={formData.departureTimeHotel} onChange={handleInputChange} highlight />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                      <InputGroup label="Fecha" name="dateDeparture" type="date" value={formData.dateDeparture} onChange={handleInputChange} />
                      <InputGroup label="Hora Vuelo" name="departureTimeFlight" type="time" value={formData.departureTimeFlight} onChange={handleInputChange} />
                    </div>
                  </div>
                </div>

                <div className="mt-12 flex flex-col sm:flex-row gap-4 pt-8 border-t border-gray-50">
                  <button onClick={handleSave} className="flex-1 py-5 bg-[#0a305e] text-white rounded-[24px] font-black uppercase text-[11px] tracking-[0.2em] shadow-xl shadow-blue-100 hover:bg-slate-900 hover:scale-[1.01] active:scale-95 transition-all">
