    tourName: '',
    observations: '',
    origin: '', 
    destination: '', 
    arrivalName: '',
    arrivalDestination: '',
    peopleCountArrival: 1,
    departureName: '',
    departureDestination: '',
    peopleCountDeparture: 1,
