export const getWhatsAppLink = (number: string, message: string) => {
  const numberClean = number.replace(/\D/g, '');
  return `https://wa.me/${numberClean}?text=${encodeURIComponent(message)}`;
};

export const getGoogleMapsLink = (query: string) => {
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
};

export const generateWhatsAppMessage = (res: Reservation) => {
  const showArrival = res.serviceType === "Llegada y Salida" || res.serviceType === "Solo Llegada";
  const showDeparture = res.serviceType === "Llegada y Salida" || res.serviceType === "Solo Salida";
  const showTransfer = res.serviceType === "Solo Traslado";
  const showTour = res.serviceType === "Tour o Excursión";

  let msg = `*QUICK TRAVEL CANCUN - VOUCHER OFICIAL*\n`;
  msg += `*Servicio:* ${res.serviceType}${res.transferSubtype ? ` (${res.transferSubtype})` : ''}\n`;
  msg += `----------------------------------\n`;
  msg += `*Reserva:* ${res.reservationNo}\n`;
  msg += `*Pasajero:* ${res.name}\n\n`;

  if (showArrival) {
    msg += `*LLEGADA:*\n`;
    msg += `📍 Origen: ${res.origin}\n`;
    msg += `🏨 Destino: ${res.arrivalDestination}\n`;
    msg += `📅 Fecha: ${res.dateArrival}\n`;
    msg += `✈️ Vuelo: ${res.flightNoArrival}\n`;
    msg += `🕒 Hora: ${res.arrivalTime}\n`;
    msg += `👤 Pax: ${res.peopleCountArrival}\n\n`;
  }

  if (showDeparture) {
    msg += `*SALIDA:*\n`;
    msg += `📍 Origen: ${res.originDeparture}\n`;
    msg += `🏨 Destino: ${res.departureDestination}\n`;
    msg += `📅 Fecha: ${res.dateDeparture}\n`;
    msg += `🚐 *Pick-up:* ${res.departureTimeHotel}\n`;
    msg += `✈️ Vuelo: ${res.departureTimeFlight}\n`;
    msg += `👤 Pax: ${res.peopleCountDeparture}\n\n`;
  }

  if (showTransfer) {
    msg += `*TRASLADO:*\n`;
    msg += `📍 Origen: ${res.originDeparture}\n`;
    msg += `🏨 Destino: ${res.departureDestination}\n`;
    msg += `📅 Fecha: ${res.dateDeparture}\n`;
    msg += `🕒 *Hora Inicio:* ${res.departureTimeHotel}\n`;
    msg += `🕒 *Hora Regreso:* ${res.departureTimeFlight}\n`;
    msg += `👤 Pax: ${res.peopleCountDeparture}\n\n`;

    if (res.transferSubtype === "Traslado Múltiple" && res.extraLegs && res.extraLegs.length > 0) {
      msg += `*TRAMOS ADICIONALES:*\n`;
      res.extraLegs.forEach((leg, i) => {
        msg += `[${i+1}] 📍 ${leg.origin} -> 🏨 ${leg.destination}\n`;
        msg += `📅 ${leg.date} | 🕒 ${leg.startTime} - ${leg.returnTime} | 👤 Pax: ${leg.pax}\n\n`;
      });
    }
  }

  if (showTour) {
    msg += `*TOUR / EXCURSIÓN:*\n`;
    msg += `🌟 *Tour:* ${res.tourName || '---'}\n`;
    msg += `📋 Tipo: ${res.tourType || '---'}\n`;
    msg += `📍 Hotel/Punto: ${res.originDeparture}\n`;
    msg += `📅 Fecha: ${res.dateDeparture}\n`;
    msg += `🚐 *Pick-up:* ${res.departureTimeHotel}\n`;
    msg += `👤 Pax: ${res.peopleCountDeparture}\n`;
    if (res.observations) {
      msg += `📝 Notas: ${res.observations}\n`;
    }
    msg += `\n`;
  }

  msg += `*SALDOS:*\n`;
  msg += `💵 MXN: $${res.balanceMxn}\n`;
  msg += `💵 USD: $${res.balanceUsd}\n\n`;
  msg += `_Propina no incluida. ¡Buen viaje!_`;

  return msg.trim();
};

export const downloadAsPDF = async (elementId: string, filename: string) => {
  const element = document.getElementById(elementId);
  if (!element) return;

  try {
    const canvas = await html2canvas(element, {
      scale: 3,
      useCORS: true,
      logging: false,
      backgroundColor: '#ffffff',
      windowWidth: 800 // Forced width for consistent layout
    });

    const imgData = canvas.toDataURL('image/png', 1.0);
    const pdf = new jsPDF({
      orientation: 'portrait',
      unit: 'mm',
      format: 'a4'
    });

    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = pdf.internal.pageSize.getHeight();
    const margin = 5;
    const displayWidth = pdfWidth - (margin * 2);
    const imgProps = pdf.getImageProperties(imgData);
    const displayHeight = (imgProps.height * displayWidth) / imgProps.width;

    pdf.addImage(imgData, 'PNG', margin, margin, displayWidth, displayHeight);
    pdf.save(filename);
  } catch (error) {
    console.error('Error al generar PDF:', error);
    alert('Error al generar el PDF.');
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Reservation, TransferLeg } from './types';
import { CONTACTS, COMPANY_EMAIL, SHEET_NAME, Logo, TOUR_LIST } from './constants';
import { getWhatsAppLink, generateWhatsAppMessage, downloadAsPDF } from './utils';
import VoucherPreview from './components/VoucherPreview';

const GOOGLE_SHEET_URL = "https://docs.google.com/spreadsheets/d/1mKo7CYV3Wf1LmuuslP0DmV9UTUFvGvE1JKFQihqFLvE/edit?usp=drivesdk";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'history'>('create');
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [currentVoucher, setCurrentVoucher] = useState<Reservation | null>(null);
  const [syncing, setSyncing] = useState(false);
  const [isExportingPDF, setIsExportingPDF] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [tourSuggestions, setTourSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const [showWSModal, setShowWSModal] = useState<{
    show: boolean;
    type: 'driver' | 'staff' | 'customer' | null;
    number: string;
    label: string;
  }>({ show: false, type: null, number: '', label: '' });

  const generateNewId = () => {
    const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    let randomPart = '';
    for (let i = 0; i < 6; i++) {
      randomPart += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return `QTC${randomPart}`;
  };

  const initialFormState: Omit<Reservation, 'id' | 'createdAt'> = {
    reservationNo: '',
    name: '',
    serviceType: 'Llegada y Salida',
    transferSubtype: 'Traslado Sencillo',
    tourType: 'Tour Compartido',
    tourName: '',
    observations: '',
    origin: '', 
    destination: '', 
    arrivalName: '',
    arrivalDestination: '',
    peopleCountArrival: 1,
    departureName: '',
    departureDestination: '',
    peopleCountDeparture: 1,
    dateArrival: new Date().toISOString().split('T')[0],
    dateDeparture: new Date().toISOString().split('T')[0],
    arrivalTime: '',
    flightNoArrival: '',
    airlineArrival: '',
    originDeparture: '',
    departureTimeHotel: '',
    departureTimeFlight: '',
    extraLegs: [],
    peopleCount: 1,
    balanceMxn: 0,
    balanceUsd: 0,
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    const saved = localStorage.getItem('qt_reservations');
    if (saved) {
      const parsed = JSON.parse(saved);
      setReservations(parsed);
    }
    if (!editingId && formData.reservationNo === '') {
      setFormData(prev => ({ ...prev, reservationNo: generateNewId() }));
    }
  }, [editingId, formData.reservationNo]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;

    if (name === 'tourName') {
      if (value.length >= 3) {
        const filtered = TOUR_LIST.filter(tour => 
          tour.toLowerCase().includes(value.toLowerCase())
        );
        setTourSuggestions(filtered);
        setShowSuggestions(filtered.length > 0);
      } else {
        setShowSuggestions(false);
      }
    }

    setFormData(prev => ({ 
      ...prev, 
      [name]: (name === 'peopleCount' || name === 'peopleCountArrival' || name === 'peopleCountDeparture' || name === 'balanceMxn' || name === 'balanceUsd') 
        ? parseFloat(value) || 0 
        : value 
    }));
  };

  const handleTourSelect = (tour: string) => {
    setFormData(prev => ({ ...prev, tourName: tour }));
    setShowSuggestions(false);
  };

  const addTransferLeg = () => {
    const newLeg: TransferLeg = {
      id: Date.now().toString(),
      origin: '',
      destination: '',
      pax: formData.peopleCountDeparture,
      startTime: '',
      returnTime: '',
      date: new Date().toISOString().split('T')[0]
    };
    setFormData(prev => ({
      ...prev,
      extraLegs: [...(prev.extraLegs || []), newLeg]
    }));
  };

  const updateTransferLeg = (id: string, field: keyof TransferLeg, value: any) => {
    setFormData(prev => ({
      ...prev,
      extraLegs: prev.extraLegs?.map(leg => 
        leg.id === id ? { ...leg, [field]: value } : leg
      )
    }));
  };

  const removeTransferLeg = (id: string) => {
    setFormData(prev => ({
      ...prev,
      extraLegs: prev.extraLegs?.filter(leg => leg.id !== id)
    }));
  };

  const showUIMessage = (msg: string) => {
    setSuccessMessage(msg);
    setTimeout(() => setSuccessMessage(null), 5000);
  };

  const handleSave = () => {
    const finalData = { 
      ...formData, 
      name: formData.arrivalName || formData.departureName || '',
      peopleCount: formData.peopleCountArrival || formData.peopleCountDeparture || 0
    };

    let updated: Reservation[];
    let savedRes: Reservation;

    if (editingId) {
      updated = reservations.map(res => {
        if (res.id === editingId) {
          savedRes = { ...finalData, id: editingId, createdAt: res.createdAt } as Reservation;
          return savedRes;
        }
        return res;
      });
      showUIMessage(`✅ Reserva ${formData.reservationNo} actualizada.`);
    } else {
      const newRes: Reservation = {
        ...finalData,
        id: Date.now().toString(),
        createdAt: new Date().toISOString(),
      } as Reservation;
      savedRes = newRes;
      updated = [newRes, ...reservations];
      showUIMessage(`✅ Reserva ${newRes.reservationNo} guardada.`);
    }

    setReservations(updated);
    localStorage.setItem('qt_reservations', JSON.stringify(updated));
    setCurrentVoucher(savedRes!);

    setEditingId(null);
    setFormData({
      ...initialFormState,
      reservationNo: generateNewId()
    });
  };

  const handleEdit = (res: Reservation) => {
    setEditingId(res.id);
    const { id, createdAt, ...dataToEdit } = res;
    setFormData(dataToEdit as any);
    setActiveTab('create');
    setCurrentVoucher(null);
  };

  const handleSyncToSheets = async () => {
    setSyncing(true);
    setTimeout(() => {
      setSyncing(false);
      window.open(GOOGLE_SHEET_URL, '_blank');
      showUIMessage(`📊 Datos sincronizados.`);
    }, 1500);
  };

  const handleExportPDF = async () => {
    if (!currentVoucher) return;
    setIsExportingPDF(true);
    await downloadAsPDF('voucher-to-print', `Voucher_${currentVoucher.reservationNo}.pdf`);
    setIsExportingPDF(false);
  };

  const triggerWhatsAppModal = (type: 'driver' | 'staff' | 'customer') => {
    const voucher = currentVoucher || formData;
    let defaultNum = '';
    let label = '';
    if (type === 'driver') { defaultNum = CONTACTS.DRIVER.number; label = 'Chofer'; }
    if (type === 'staff') { defaultNum = CONTACTS.STAFF.number; label = 'Staff'; }
    if (type === 'customer') { defaultNum = CONTACTS.CUSTOMER.number; label = 'Cliente'; }
    setShowWSModal({ show: true, type, number: defaultNum, label });
  };

  const confirmAndSendWhatsApp = () => {
    const voucher = currentVoucher || formData;
    const message = generateWhatsAppMessage(voucher as Reservation);
    window.open(getWhatsAppLink(showWSModal.number, message), '_blank');
