                <button onClick={confirmAndSendWhatsApp} className="flex-2 py-4 bg-[#25D366] text-white rounded-2xl font-black uppercase text-[10px]">Enviar</button>
              </div>
            </div>
          </div>
        </div>
      )}

      {successMessage && (
