                <div className="w-2 h-2 bg-yellow-400 rounded-full animate-pulse"></div>
                <span className="text-[9px] font-black text-orange-600 uppercase italic">Pago Directo al Chofer</span>
              </div>
            </div>
          </div>

          {/* Instructions Card */}
          <div className="bg-slate-50 p-5 rounded-2xl border border-slate-200">
            <h4 className="text-[10px] font-black uppercase text-[#0a305e] mb-3">Instrucciones de Viaje</h4>
            <ul className="space-y-3 text-[9px] font-bold text-slate-600 leading-tight">
              <li className="flex gap-2">
                <i className="fas fa-info-circle text-[#0a305e] mt-0.5"></i>
                <span>LLEGADAS: El chofer le espera afuera de la terminal con su nombre.</span>
              </li>
              <li className="flex gap-2">
                <i className="fas fa-clock text-[#0a305e] mt-0.5"></i>
                <span>PICK-UPS: Estar listo 10 minutos antes en el lobby u origen.</span>
              </li>
              <li className="flex gap-2">
                <i className="fas fa-user-friends text-[#0a305e] mt-0.5"></i>
                <span>ASISTENCIA: +52 998 131 7824 (Atención 24/7).</span>
              </li>
            </ul>
          </div>

          {/* Observations Box */}
          {reservation.observations && (
            <div className="bg-yellow-50/50 p-4 rounded-2xl border border-yellow-100">
              <span className="block text-[8px] text-yellow-700 uppercase font-black mb-1">Notas del Operador</span>
              <p className="text-[9px] text-gray-700 font-medium italic leading-relaxed">"{reservation.observations}"</p>
            </div>
          )}

          {/* Warning Policies */}
          <div className="p-4 border-l-4 border-red-500 bg-red-50/30 rounded-r-xl">
             <p className="text-[8px] text-red-700 font-black uppercase leading-tight">
               La propina para el personal de servicio no está incluida y queda a su discreción.
             </p>
          </div>
        </div>
      </div>

      {/* 3. Footer Section */}
      <div className="mt-8 pt-4 border-t border-gray-100 flex justify-between items-center relative z-10">
        <div className="flex items-center gap-4 text-[8px] text-gray-400 font-black uppercase tracking-[0.2em]">
          <span>© Quick Travel Cancun</span>
          <span className="w-1 h-1 bg-gray-200 rounded-full"></span>
          <span>Soporte: quicktravelincancun@gmail.com</span>
        </div>
        <div className="text-[8px] text-[#0a305e] font-black uppercase tracking-[0.2em]">
          SISTEMA DE GESTIÓN V4.0
        </div>
      </div>
    </div>
  );
};

