export default App;

import React, { useState, useEffect } from 'react';
import { Reservation, TransferLeg, TourLeg } from './types';
import { CONTACTS, COMPANY_EMAIL, SHEET_NAME, Logo, TOUR_LIST } from './constants';
import { getWhatsAppLink, generateWhatsAppMessage, downloadAsPDF } from './utils';
import VoucherPreview from './components/VoucherPreview';

const GOOGLE_SHEET_URL = "https://docs.google.com/spreadsheets/d/1mKo7CYV3Wf1LmuuslP0DmV9UTUFvGvE1JKFQihqFLvE/edit?gid=0#gid=0";

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'create' | 'history'>('create');
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [currentVoucher, setCurrentVoucher] = useState<Reservation | null>(null);
  const [syncing, setSyncing] = useState(false);
  const [isExportingPDF, setIsExportingPDF] = useState(false);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [tourSuggestions, setTourSuggestions] = useState<{index: number, list: string[]}>({ index: -1, list: [] });
  const [pdfSingleTourIndex, setPdfSingleTourIndex] = useState<number | null>(null);

  const [showWSModal, setShowWSModal] = useState<{
    show: boolean;
    type: 'driver' | 'staff' | 'customer' | null;
    number: string;
    label: string;
  }>({ show: false, type: null, number: '', label: '' });

  const generateNewId = () => {
    const chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    let randomPart = '';
    for (let i = 0; i < 6; i++) {
      randomPart += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return `QTC${randomPart}`;
  };

  const initialFormState: Omit<Reservation, 'id' | 'createdAt'> = {
    reservationNo: '',
    name: '',
    serviceType: 'Llegada y Salida',
    transferSubtype: 'Traslado Sencillo',
    tourType: 'Tour Compartido',
    tourName: '',
    observations: '',
    origin: '', 
    destination: '', 
    arrivalName: '',
    arrivalDestination: '',
    peopleCountArrival: 1,
    departureName: '',
    departureDestination: '',
    peopleCountDeparture: 1,
    dateArrival: new Date().toISOString().split('T')[0],
    dateDeparture: new Date().toISOString().split('T')[0],
    arrivalTime: '',
    flightNoArrival: '',
    airlineArrival: '',
    originDeparture: '',
    departureTimeHotel: '',
    departureTimeFlight: '',
    extraLegs: [],
    extraTours: [],
    peopleCount: 1,
    balanceMxn: 0,
    balanceUsd: 0,
  };

  const [formData, setFormData] = useState(initialFormState);

  useEffect(() => {
    const saved = localStorage.getItem('qt_reservations');
    if (saved) {
      const parsed = JSON.parse(saved);
      setReservations(parsed);
    }
    if (!editingId && formData.reservationNo === '') {
      setFormData(prev => ({ ...prev, reservationNo: generateNewId() }));
    }
  }, [editingId, formData.reservationNo]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;

    if (name === 'tourName') {
      if (value.length >= 3) {
        const filtered = TOUR_LIST.filter(tour => tour.toLowerCase().includes(value.toLowerCase()));
        setTourSuggestions({ index: 0, list: filtered });
      } else {
        setTourSuggestions({ index: -1, list: [] });
      }
    }

    setFormData(prev => ({ 
      ...prev, 
      [name]: (name.includes('peopleCount') || name === 'balanceMxn' || name === 'balanceUsd') 
        ? parseFloat(value) || 0 
        : value 
    }));
  };

  const handleTourLegInputChange = (id: string, field: keyof TourLeg, value: any) => {
    if (field === 'tourName' && typeof value === 'string' && value.length >= 3) {
      const idx = formData.extraTours?.findIndex(t => t.id === id) ?? -1;
      const filtered = TOUR_LIST.filter(tour => tour.toLowerCase().includes(value.toLowerCase()));
      setTourSuggestions({ index: idx + 1, list: filtered });
    } else if (field === 'tourName') {
      setTourSuggestions({ index: -1, list: [] });
    }

    setFormData(prev => ({
      ...prev,
      extraTours: prev.extraTours?.map(tour => 
        tour.id === id ? { ...tour, [field]: value } : tour
      )
    }));
  };

  const handleTourSelect = (tour: string, index: number) => {
    if (index === 0) {
      setFormData(prev => ({ ...prev, tourName: tour }));
    } else {
      const tourId = formData.extraTours?.[index - 1]?.id;
      if (tourId) {
        handleTourLegInputChange(tourId, 'tourName', tour);
      }
    }
    setTourSuggestions({ index: -1, list: [] });
  };

  const addTourLeg = () => {
    const newLeg: TourLeg = {
      id: Date.now().toString(),
      tourName: '',
      tourType: formData.tourType || 'Tour Compartido',
      originDeparture: formData.originDeparture,
      peopleCountDeparture: formData.peopleCountDeparture,
      departureTimeHotel: '',
      dateDeparture: formData.dateDeparture,
      observations: ''
    };
    setFormData(prev => ({
      ...prev,
      extraTours: [...(prev.extraTours || []), newLeg]
    }));
  };

  const removeTourLeg = (id: string) => {
    setFormData(prev => ({
      ...prev,
      extraTours: prev.extraTours?.filter(tour => tour.id !== id)
    }));
  };

  const addTransferLeg = () => {
    const newLeg: TransferLeg = {
      id: Date.now().toString(),
      origin: '',
      destination: '',
      pax: formData.peopleCountDeparture,
      startTime: '',
      returnTime: '',
      date: new Date().toISOString().split('T')[0]
    };
    setFormData(prev => ({
      ...prev,
      extraLegs: [...(prev.extraLegs || []), newLeg]
    }));
  };

  const updateTransferLeg = (id: string, field: keyof TransferLeg, value: any) => {
    setFormData(prev => ({
      ...prev,
      extraLegs: prev.extraLegs?.map(leg => 
        leg.id === id ? { ...leg, [field]: value } : leg
      )
    }));
  };

  const removeTransferLeg = (id: string) => {
    setFormData(prev => ({
      ...prev,
      extraLegs: prev.extraLegs?.filter(leg => leg.id !== id)
    }));
  };

  const showUIMessage = (msg: string) => {
    setSuccessMessage(msg);
    setTimeout(() => setSuccessMessage(null), 5000);
  };

  const handleSave = () => {
    const finalData = { 
      ...formData, 
      name: formData.arrivalName || formData.departureName || formData.name || '',
      peopleCount: formData.peopleCountArrival || formData.peopleCountDeparture || formData.peopleCount || 0
    };

    let updated: Reservation[];
    let savedRes: Reservation;

    if (editingId) {
      updated = reservations.map(res => {
        if (res.id === editingId) {
          savedRes = { ...finalData, id: editingId, createdAt: res.createdAt } as Reservation;
          return savedRes;
        }
        return res;
      });
      showUIMessage(`✅ Reserva ${formData.reservationNo} actualizada.`);
    } else {
      const newRes: Reservation = {
        ...finalData,
        id: Date.now().toString(),
        createdAt: new Date().toISOString(),
      } as Reservation;
      savedRes = newRes;
      updated = [newRes, ...reservations];
      showUIMessage(`✅ Reserva ${newRes.reservationNo} guardada.`);
    }

    setReservations(updated);
    localStorage.setItem('qt_reservations', JSON.stringify(updated));
    setCurrentVoucher(savedRes!);

    setEditingId(null);
    setFormData({
      ...initialFormState,
      reservationNo: generateNewId()
    });
  };

  const handleEdit = (res: Reservation) => {
    setEditingId(res.id);
    const { id, createdAt, ...dataToEdit } = res;
    setFormData(dataToEdit as any);
    setActiveTab('create');
    setCurrentVoucher(null);
  };

  const handleSyncToSheets = async () => {
    const data = currentVoucher || {
        ...formData, 
        name: formData.arrivalName || formData.departureName || formData.name || '',
        peopleCount: formData.peopleCountArrival || formData.peopleCountDeparture || formData.peopleCount || 0,
        createdAt: new Date().toISOString()
    };

    const formatDate = (dateStr: string) => {
        if (!dateStr) return '-';
        const [y, m, d] = dateStr.split('-');
        return `${d}/${m}/${y}`;
    };

    const rows: string[] = [];
    const balanceStr = `MXN: $${data.balanceMxn} | USD: $${data.balanceUsd}`;

    const addRow = (
        date: string, 
        time: string, 
        service: string, 
        origin: string, 
        dest: string, 
        pax: number, 
        name: string, 
        flight: string, 
        bal: string,
        idSuffix: string = ''
    ) => {
        // COLUMNS:
        // no reservacion | FECHA | HORA | SERVICIO | ORIGEN | DESTINO | PAXS | NOMBRE | VUELO/HABITA | BALANCE | CHOFER | COMPAÑÍA | VENDEDOR
        rows.push([
            data.reservationNo + idSuffix,
            formatDate(date),
            time || '-',
            service,
            origin || '-',
            dest || '-',
            pax,
            name,
            flight || '-',
            bal,
            "", // CHOFER
            "Quick Travel", // COMPAÑÍA
            "" // VENDEDOR
        ].join('\t'));
    };

    if (data.serviceType === "Llegada y Salida") {
        // Arrival Row
        addRow(
            data.dateArrival, 
            data.arrivalTime, 
            "Llegada", 
            data.origin, 
            data.arrivalDestination, 
            data.peopleCountArrival, 
            data.arrivalName || data.name, 
            `${data.airlineArrival || ''} ${data.flightNoArrival || ''}`.trim(), 
            balanceStr
        );
        // Departure Row
        addRow(
            data.dateDeparture, 
            data.departureTimeHotel, 
            "Salida", 
            data.originDeparture, 
            data.departureDestination, 
            data.peopleCountDeparture, 
            data.departureName || data.name, 
            data.departureTimeFlight ? `Vuelo ${data.departureTimeFlight}` : '', 
            "0"
        );
    } else if (data.serviceType === "Solo Llegada") {
        addRow(
            data.dateArrival, 
            data.arrivalTime, 
            "Llegada", 
            data.origin, 
            data.arrivalDestination, 
            data.peopleCountArrival, 
            data.arrivalName || data.name, 
            `${data.airlineArrival || ''} ${data.flightNoArrival || ''}`.trim(), 
            balanceStr
        );
    } else if (data.serviceType === "Solo Salida") {
        addRow(
            data.dateDeparture, 
            data.departureTimeHotel, 
            "Salida", 
            data.originDeparture, 
            data.departureDestination, 
            data.peopleCountDeparture, 
            data.departureName || data.name, 
            data.departureTimeFlight ? `Vuelo ${data.departureTimeFlight}` : '', 
            balanceStr
        );
    } else if (data.serviceType === "Solo Traslado") {
        addRow(
            data.dateDeparture, 
            data.departureTimeHotel, 
            `Traslado (${data.transferSubtype})`, 
            data.originDeparture, 
            data.departureDestination, 
            data.peopleCountDeparture, 
            data.departureName || data.name, 
            "", 
            balanceStr
        );
        if (data.transferSubtype === "Traslado Múltiple" && data.extraLegs) {
            data.extraLegs.forEach((leg, i) => {
                addRow(
                    leg.date,
                    leg.startTime,
                    "Traslado Extra",
                    leg.origin,
                    leg.destination,
                    leg.pax,
                    data.departureName || data.name,
                    "",
                    "0",
                    `-L${i+1}`
                );
            });
        }
    } else if (data.serviceType === "Tour o Excursión") {
        addRow(
            data.dateDeparture,
            data.departureTimeHotel,
            `Tour: ${data.tourName}`,
            data.originDeparture,
            "-", 
            data.peopleCountDeparture,
            data.departureName || data.name,
            "",
            balanceStr
        );
         if (data.extraTours) {
            data.extraTours.forEach((tour, i) => {
                addRow(
                    tour.dateDeparture,
                    tour.departureTimeHotel,
                    `Tour: ${tour.tourName}`,
                    tour.originDeparture,
                    "-",
                    tour.peopleCountDeparture,
                    data.departureName || data.name,
                    "",
                    "0",
                    `-T${i+1}`
                );
            });
        }
    }

    const tsv = rows.join('\n');

    try {
      await navigator.clipboard.writeText(tsv);
      setSyncing(true);
      showUIMessage(`📋 Copiado! Pega (Ctrl+V) en la hoja.`);

      setTimeout(() => {
        setSyncing(false);
        window.open(GOOGLE_SHEET_URL, '_blank');
      }, 1000);
    } catch (err) {
      console.error('Copy failed', err);
      window.open(GOOGLE_SHEET_URL, '_blank');
      showUIMessage(`⚠️ No se pudo copiar. Abriendo hoja.`);
    }
  };

  // Helper for sequential state-dependent downloads
  const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

  const handleExportPDF = async () => {
    if (!currentVoucher) return;
    setIsExportingPDF(true);

    if (currentVoucher.serviceType === "Tour o Excursión") {
      // 1. Download Primary Tour
      setPdfSingleTourIndex(0);
      await sleep(200); // Wait for re-render
      await downloadAsPDF('voucher-to-print', `Voucher_${currentVoucher.reservationNo}_Tour_1.pdf`);

      // 2. Download Extra Tours
      if (currentVoucher.extraTours && currentVoucher.extraTours.length > 0) {
        for (let i = 0; i < currentVoucher.extraTours.length; i++) {
          setPdfSingleTourIndex(i + 1);
          await sleep(200);
          await downloadAsPDF('voucher-to-print', `Voucher_${currentVoucher.reservationNo}_Tour_${i + 2}.pdf`);
        }
      }

      // Reset
      setPdfSingleTourIndex(null);
    } else {
      await downloadAsPDF('voucher-to-print', `Voucher_${currentVoucher.reservationNo}.pdf`);
    }

    setIsExportingPDF(false);
  };

