            <div className="bg-[#0a305e] p-8 text-white text-center">
              <i className="fab fa-whatsapp text-4xl text-green-400 mb-4 block"></i>
              <h3 className="text-2xl font-black uppercase">Enviar a {showWSModal.label}</h3>
