                  <DetailRow label="Nombre" value={reservation.departureName} className="col-span-2" highlight />
                  <DetailRow label="Recolección (Pick-up)" value={reservation.originDeparture} isLink />
                  <DetailRow label="Hacia" value={reservation.departureDestination} />
                  <DetailRow label="Fecha" value={reservation.dateDeparture} />
                  <DetailRow label="Pick-up Hotel" value={reservation.departureTimeHotel} className="text-[#f05a28]" highlight />
                  <DetailRow label="Hora de Vuelo" value={reservation.departureTimeFlight} />
