                      <p className="text-[9px] text-slate-600">{tour.obs}</p>
                   </div>
                )}
              </div>
            ))}

            {showTransfer && (
              <div className="bg-white p-4 rounded-2xl border border-blue-50 shadow-sm">
                <SectionHeader label="Servicio de Traslado" icon="fa-exchange-alt" color="blue" />
                <div className="grid grid-cols-2 gap-y-3 gap-x-4 mt-4">
                  <DetailRow label="Nombre" value={reservation.departureName} className="col-span-2" highlight />
                  <DetailRow label="Desde" value={reservation.originDeparture} isLink />
                  <DetailRow label="Hasta" value={reservation.departureDestination} />
                  <DetailRow label="Fecha" value={reservation.dateDeparture} />
                  <DetailRow label="Hora Inicio" value={reservation.departureTimeHotel} className="text-blue-700 font-black" highlight />
                  <DetailRow label="Hora Regreso" value={reservation.departureTimeFlight} />
                </div>
                {reservation.transferSubtype === "Traslado Múltiple" && reservation.extraLegs && reservation.extraLegs.length > 0 && (
                  <div className="mt-4 pt-4 border-t border-gray-100 space-y-4">
                     {reservation.extraLegs.map((leg, i) => (
                       <div key={leg.id} className="grid grid-cols-2 gap-2 text-[10px]">
                         <span className="font-bold uppercase text-gray-400 col-span-2">Tramo Extra #{i+1}</span>
