    </div>
  );
};

const DetailRow: React.FC<{ label: string; value: string | number; isLink?: boolean; className?: string; size?: 'normal' | 'large'; highlight?: boolean }> = ({ label, value, isLink, className, size = 'normal', highlight = false }) => (
  <div className={className}>
    <span className="block text-[7px] text-gray-400 uppercase font-black tracking-widest mb-1">{label}</span>
    {isLink && value ? (
      <a 
        href={getGoogleMapsLink(String(value))} 
        target="_blank" 
        rel="noopener noreferrer"
        className={`text-blue-600 font-black hover:text-blue-800 transition-colors flex items-center gap-1.5 ${size === 'large' ? 'text-lg' : 'text-[11px]'}`}
      >
        <span className="truncate">{value}</span>
        <i className="fas fa-map-marker-alt text-[8px] opacity-40"></i>
      </a>
    ) : (
      <span className={`text-gray-900 font-black tracking-tight ${size === 'large' ? 'text-xl' : 'text-[11px]'} ${highlight ? 'text-[#f05a28]' : ''}`}>
        {value || '---'}
      </span>
