    blue: "bg-blue-50 text-blue-700 border-blue-100",
    purple: "bg-purple-50 text-purple-700 border-purple-100"
  };
  return (
    <div className="flex items-center gap-2 border-b-2 border-gray-50 pb-2">
      <div className={`w-8 h-8 ${colorMap[color]} border rounded-lg flex items-center justify-center text-sm`}>
        <i className={`fas ${icon}`}></i>
      </div>
      <h3 className="text-[10px] font-black text-gray-800 uppercase tracking-widest">{label}</h3>
    </div>
  );
};

const Badge: React.FC<{ label: string; value: string; color: string }> = ({ label, value, color }) => {
  const colorMap: Record<string, string> = {
    blue: "bg-blue-50 text-blue-700 border-blue-100",
    orange: "bg-orange-50 text-orange-700 border-orange-100",
    purple: "bg-purple-50 text-purple-700 border-purple-100"
