  return (
    <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full border ${colorMap[color]} shadow-sm`}>
      <span className="text-[7px] uppercase font-black opacity-50">{label}:</span>
      <span className="text-[9px] font-black uppercase whitespace-nowrap">{value}</span>
