const DetailRow: React.FC<{ label: string; value: string | number | undefined | null; isLink?: boolean; className?: string; size?: 'normal' | 'large'; highlight?: boolean }> = ({ label, value, isLink, className, size = 'normal', highlight = false }) => {
  const displayValue = (value !== undefined && value !== null && value !== '') ? value : '---';

  return (
    <div className={className}>
      <span className="block text-[7px] text-gray-400 uppercase font-black tracking-widest mb-1">{label}</span>
      {isLink && displayValue !== '---' ? (
        <a 
          href={getGoogleMapsLink(String(displayValue))} 
          target="_blank" 
          rel="noopener noreferrer"
          className={`text-blue-600 font-black hover:text-blue-800 transition-colors flex items-center gap-1.5 ${size === 'large' ? 'text-lg' : 'text-[11px]'}`}
        >
          <span className="truncate">{displayValue}</span>
          <i className="fas fa-map-marker-alt text-[8px] opacity-40"></i>
        </a>
      ) : (
        <span className={`text-gray-900 font-black tracking-tight ${size === 'large' ? 'text-xl' : 'text-[11px]'} ${highlight ? 'text-[#f05a28]' : ''}`}>
          {displayValue}
        </span>
      )}
    </div>
  );
};

const SectionHeader: React.FC<{ label: string; icon: string; color: string }> = ({ label, icon, color }) => {
  const colorMap: Record<string, string> = {
    green: "bg-green-50 text-green-600 border-green-100",
    orange: "bg-orange-50 text-orange-600 border-orange-100",
    blue: "bg-blue-50 text-blue-700 border-blue-100",
    purple: "bg-purple-50 text-purple-700 border-purple-100"
  };
  return (
    <div className="flex items-center gap-2 border-b-2 border-gray-50 pb-2">
      <div className={`w-8 h-8 ${colorMap[color]} border rounded-lg flex items-center justify-center text-sm`}>
        <i className={`fas ${icon}`}></i>
      </div>
      <h3 className="text-[10px] font-black text-gray-800 uppercase tracking-widest">{label}</h3>
    </div>
  );
};

const Badge: React.FC<{ label: string; value: string; color: string }> = ({ label, value, color }) => {
  const colorMap: Record<string, string> = {
    blue: "bg-blue-50 text-blue-700 border-blue-100",
    orange: "bg-orange-50 text-orange-700 border-orange-100",
    purple: "bg-purple-50 text-purple-700 border-purple-100"
  };
  return (
    <div className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full border ${colorMap[color]} shadow-sm`}>
      <span className="text-[7px] uppercase font-black opacity-50">{label}:</span>
      <span className="text-[9px] font-black uppercase whitespace-nowrap">{value}</span>
    </div>
  );
};

